"""Short, choice-specific feedback for professional expressions."""
expression_notes={
'Respecter une échéance':{'attend':'Attend veut dire assister à un événement. Une date limite n’est pas un événement auquel on assiste.','join':'Join veut dire rejoindre une personne ou un groupe.','arrive':'Arrive veut dire arriver. Il ne se place pas directement devant the deadline ici.'},
'Passer une commande':{'spend':'Spend veut dire dépenser de l’argent ou passer du temps.','borrow':'Borrow veut dire emprunter. Ici, on commande des produits.','attend':'Attend veut dire assister à une réunion ou à un événement.'},
'Demander à obtenir':{'at':'At sert notamment à indiquer un lieu. Pour demander à obtenir, on dit apply for.','with':'With veut dire avec. Il ne complète pas cette expression.','on':'On ne convient pas ici : apply for indique ce qu’on demande à obtenir.'},
'Responsable de':{'at':'At convient dans good at, mais pas pour dire responsable de.','with':'With ne complète pas responsible pour indiquer une tâche.','by':'By ne complète pas responsible pour indiquer la responsabilité.'},
'Participer à':{'make':'Make part in n’est pas l’expression participer à.','do':'Do your part veut dire faire sa part, mais do part in ne convient pas.','give':'Give veut dire donner. L’expression participer à est take part in.'},
'À jour':{'day':'Day veut dire jour. On ne traduit pas à jour mot par mot.','year':'Year veut dire année. L’expression correcte reste up to date.','hour':'Hour veut dire heure. Up to hour ne signifie pas à jour.'},
'Gratuit':{'price':'Price veut dire prix. L’expression est free of charge.','salary':'Salary veut dire salaire. Ici, on parle du prix d’un service.','invoice':'Invoice veut dire facture. Free of invoice ne signifie pas gratuit.'},
'Sous garantie':{'invoice':'Invoice est une facture, pas une garantie.','receipt':'Receipt est un reçu. Under receipt ne signifie pas sous garantie.','purchase':'Purchase signifie achat. Under purchase ne signifie pas sous garantie.'},
'Au nom de':{'purpose':'On purpose veut dire volontairement. On purpose of ne convient pas.','regard':'With regard to signifie concernant. On regard of ne convient pas.','side':'On the side of signifie du côté de ; on side of ne convient pas.'},
'À l’avance':{'ahead':'Ahead peut exprimer une avance, mais on ne dit pas in ahead.','early':'Early veut dire tôt. On dit book early, sans in.','front':'In front indique devant dans l’espace, pas à l’avance dans le temps.'},
'Être chargé de':{'duty':'On duty signifie en service. In duty of ne signifie pas responsable de.','task':'Task veut dire tâche, mais in task of ne convient pas.','role':'Role veut dire rôle. In role of ne convient pas pour cette expression.'},
'Suivre quelque chose':{'care':'On dit take care of pour s’occuper de, pas keep care of.','attention':'On dit pay attention to pour faire attention à.','part':'On dit take part in pour participer à. Ce n’est pas assurer le suivi.'},
'Peu de préavis':{'news':'News veut dire nouvelles ou actualités. At short news ne convient pas.','message':'Message veut dire message. At short message ne signifie pas avec peu de préavis.','warning':'On peut dire with little warning, mais pas at short warning pour cette expression.'},
'Par écrit':{'write':'Write est le verbe écrire. In write n’est pas correct.','wrote':'Wrote est la forme passée de write. Elle ne convient pas après in ici.','written':'Written veut dire écrit. On pourrait dire in written form, mais form manque ici.'},
'Voyage d’affaires':{'route':'Route veut dire itinéraire. Il ne désigne pas ici le voyage lui-même.','traffic':'Traffic désigne la circulation. Ce n’est pas un voyage.','transport':'Transport désigne le transport, mais business transport ne convient pas ici pour un voyage.'},
'De suite':{'line':'In a line signifie en ligne, comme des personnes alignées.','queue':'In a queue signifie dans une file d’attente.','rank':'Rank peut désigner un rang ou un grade, mais in a rank ne signifie pas de suite.'},
'Rupture de stock':{'sale':'For sale veut dire à vendre. Out of sale n’est pas l’expression rupture de stock.','invoice':'Invoice signifie facture. Out of invoice ne convient pas.','receipt':'Receipt signifie reçu. Out of receipt ne convient pas.'},
'Appareil en panne':{'stock':'Out of stock signifie qu’il n’en reste plus à vendre. Ici, l’appareil est présent mais ne fonctionne pas.','sequence':'Out of sequence veut dire dans le désordre, pas en panne.','arrangement':'Arrangement peut signifier organisation. Out of arrangement ne signifie pas en panne.'},
'Conformément à':{'according':'According s’utilise avec to : according to. On ne mélange pas avec in … with.','accordingly':'Accordingly veut dire en conséquence. In accordingly with ne convient pas.','accorded':'Accorded est une forme verbale. L’expression fixe est in accordance with.'},
'Selon':{'with':'With appartient à in accordance with. Avec according, on utilise to.','for':'According for n’est pas l’expression selon.','at':'According at n’est pas l’expression selon.'},
'Attendre avec plaisir':{'for':'On dit wait for, mais look forward to.','at':'At ne complète pas look forward.','on':'On ne complète pas look forward.'},
'Se conformer aux règles':{'to':'On dit conform to, mais comply with.','for':'For ne complète pas comply dans cette expression.','on':'On ne complète pas comply dans cette expression.'},
'Compter sur':{'at':'At ne convient pas après rely.','with':'With signifie avec. Pour compter sur, on utilise rely on.','for':'For peut introduire ce qu’on attend, mais la personne vient après on : rely on someone for help.'},
'S’occuper de demandes':{'at':'At ne convient pas après deal pour dire traiter une demande.','for':'For ne convient pas dans deal with a complaint.','on':'On ne convient pas dans cette expression. Deal with signifie traiter.'},
'Faire attention':{'make':'Make attention ne convient pas. On dit pay attention.','do':'Do attention ne convient pas. On dit pay attention.','hold':'Hold someone’s attention signifie retenir son attention. Hold attention to ne convient pas.'},
'Prendre contact':{'reach':'In reach peut vouloir dire à portée. Get in reach with ne veut pas dire contacter.','call':'Call veut dire appeler, mais get in call with ne convient pas.','speak':'Speak veut dire parler. On peut dire speak with someone, mais pas get in speak with.'},
'Effectuer':{'turn':'Turn out peut signifier se révéler. Il ne signifie pas effectuer une inspection.','put':'Put out peut signifier éteindre. Il ne signifie pas effectuer des contrôles.','bring':'Bring out peut signifier publier ou faire ressortir. Il ne signifie pas effectuer ici.'},
'Organiser une réunion':{'take':'Take up peut signifier commencer une activité ou occuper du temps. Il ne signifie pas organiser une réunion.','give':'Give up signifie abandonner.','break':'Break up signifie notamment se séparer ou disperser, pas organiser.'},
'Reporter':{'take':'Take off peut signifier décoller ou enlever.','turn':'Turn off signifie notamment éteindre un appareil.','set':'Set off peut signifier partir ou déclencher. Il ne signifie pas reporter.'},
'Refuser une offre':{'off':'Turn off signifie notamment éteindre.','into':'Turn into veut dire se transformer en. Ici, il ne s’agit pas d’une transformation.','out':'Turn out peut signifier se révéler. Il ne signifie pas refuser cette offre.'},
'Remplir les informations':{'come':'Come in veut dire entrer. Il ne signifie pas remplir les informations.','break':'Break in peut vouloir dire entrer par effraction.','set':'Set in décrit notamment une situation qui s’installe, comme le froid. Il ne signifie pas remplir.'},
'Ne plus avoir':{'away':'Run away signifie s’enfuir.','over':'Run over ne forme pas l’expression ne plus avoir avec of.','through':'Run through peut signifier parcourir ou passer en revue. Run through of ne convient pas.'},
'Licencier du personnel':{'pick':'Pick off peut signifier éliminer une cible, pas licencier du personnel.','resign':'Resign veut dire démissionner. On ne dit pas resign off employees.','remove':'Remove veut dire retirer. Il ne se construit pas avec off employees pour licencier.'},
'Examiner un problème':{'after':'Look after signifie prendre soin de. Ce n’est pas examiner la cause d’un problème.','forward':'Look forward to signifie attendre avec plaisir. Ici, il n’y a pas to et on examine un problème.','between':'Look between signifie regarder entre des choses. Cela ne convient pas ici.'},
'Annuler':{'away':'Away ne forme pas avec call l’expression annuler un événement.','down':'Call down ne signifie pas annuler ce concert.','over':'Call over peut signifier appeler quelqu’un pour qu’il s’approche. Ce n’est pas annuler.'},
'Réduire':{'make':'Make down on ne convient pas. Pour réduire, on dit cut down on.','take':'Take down peut signifier noter ou démonter, mais take down on ne signifie pas réduire.','give':'Give down on ne forme pas cette expression.'},
'Proposer une idée':{'make':'Make up a story signifie inventer une histoire, sans with. Make up with ne signifie pas trouver une solution.','bring':'Bring up a subject signifie aborder un sujet, sans with. Bring up with ne convient pas ici.','send':'Send signifie envoyer. Send up with ne signifie pas proposer une idée.'},
'Provisoirement':{'been':'Been est une forme de be. L’expression pour le moment est for the time being.','be':'Be ne complète pas cette expression fixe.','was':'Was indique le passé de be ; il ne complète pas cette expression.'},
'Dès que possible':{'than':'Than sert souvent à comparer : faster than. Ici, on utilise as … as.','like':'Like peut signifier comme, mais as soon like possible ne convient pas.','so':'So ne termine pas la construction as soon as possible.'},
'Au plus tard':{'that':'That ne complète pas la comparaison no later than.','then':'Then veut dire ensuite. Ne le confonds pas avec than, utilisé pour comparer.','as':'As s’utilise dans as late as, mais ici il faut no later than.'},
'À côté de':{'with':'With veut dire avec. Pour à côté de, on dit next to.','at':'At peut indiquer un lieu, mais next at ne convient pas.','for':'For ne complète pas next dans cette expression.'},
'En plus de':{'additional':'Additional décrit quelque chose de supplémentaire, comme additional costs. Après in ici, il faut le nom addition.','additionally':'Additionally signifie en plus, mais s’utilise sans in … to.','added':'Added veut dire ajouté. Il ne forme pas in addition to.'},
'En raison de':{'owed':'Owed veut dire dû au sens d’une dette. Ici, on indique une cause : due to.','cause':'Cause veut dire cause ou causer, mais cause to ne forme pas cette expression.','because':'Because se construit avec of devant un nom : because of fog. Ici, to est déjà présent.'},
'À la demande':{'ask':'Ask est un verbe : demander. On request utilise un nom.','requested':'Requested signifie demandé. On requested ne convient pas ici.','requesting':'Requesting est une forme en -ing. L’expression est on request.'},
'À temps':{'hour':'Hour signifie heure, mais in hour ne signifie pas à temps.','clock':'Clock signifie horloge. In clock ne convient pas.','minute':'Minute ne forme pas cette expression. In a minute voudrait dire dans une minute.'},
'D’avance sur le planning':{'before':'Before veut dire avant et peut être suivi directement d’un nom. Before of ne convient pas.','early':'Early veut dire tôt. Early of schedule ne convient pas.','front':'In front of indique devant dans l’espace. Front of schedule ne convient pas.'},
'Dans les limites du budget':{'among':'Among veut dire parmi. Il ne signifie pas dans les limites d’une somme.','between':'Between veut dire entre, par exemple entre deux montants. Ici, il n’y a qu’un budget.','along':'Along veut dire le long de. Il ne convient pas pour parler de dépenses limitées.'},
'En cas de':{'happens':'Happens est un verbe : se produit. In happens of n’est pas correct.','situation':'Situation ne forme pas l’expression in case of.','condition':'Condition peut désigner une condition. In condition of ne signifie pas en cas de.'},
'Changer d’avis':{'thought':'Thought veut dire pensée. L’expression changer d’avis est change your mind.','minded':'Minded est une forme qu’on trouve dans des adjectifs comme open-minded. Ici, il faut le nom mind.','brain':'Brain veut dire cerveau. Changer d’avis ne signifie pas changer de cerveau !'},
'Être en congé':{'left':'Left peut vouloir dire parti ou gauche. Le nom congé est leave.','leaving':'Leaving évoque l’action de partir. Ici, on cherche le nom congé.','leaves':'Leaves peut désigner des feuilles ou signifier part au présent. Dans on leave, le nom ne prend pas de s.'}
}
